__NUXT_JSONP__("/tr/feature", (function(a){return {data:[{details:{slug:"tr",pageTitle:"5 Nedende insanlarin MLI'ı seçme nedeni | Mentor Language Institute",pageDescription:"Açılışımızdan bu yana 17.000'den fazla öğrencinin İngilizce becerilerini geliştirmelerine yardımcı olduk.",section1:{title:"5 Nedende insanlarin MLI'ı seçme nedeni",image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002Fmli-mentor.jpg"},section2:{title:"Mentor Dil Enstitüsü'nün 5 Özelliği",description:["Açılışımızdan bu yana 17.000'den fazla öğrencinin İngilizce becerilerini geliştirmelerine yardımcı olduk. Öğrenciler Los Angeles'ta çok fazla İngilizce okulu olmasına rağmen neden MLI'yı seçiyorlar? MLI öğrencilerinin anketini aldık ve cevapları aşağıda."],image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002Fsurvey.jpg",notes:"Anket dönemi : Ocak-Haziran 2017 döneminde 342 öğrenci"},section3:[{title:"No.1: Uygun Fiyat",subtitle:"Harika fiyat! Haftalık $209’dan başlar. Öğleden sonra dersleri, sabah derslerine göre %40 indirimlidir!",description:["Öğrencilerin MLI'yı seçmelerinin 1 numaralı sebebi ekonomik olmasıdır.","Okulumuz'da ne kadar uzun süre katılırsanız fiyat o kadar ucuz olur. 1 ay (4 hafta) için başvuruda bulunursanız, öğrenim ücreti 1,220 $ \u002F haftalık= 305 $ 'dır. Bu zaten LA'da makul bir fiyat. Ancak, 48 hafta boyunca başvuruda bulunursanız, harç 10,032 $ \u002F haftalık = 209 ABD Dolarıdır. Lütfen oranlarımızı diğer okullarla karşılaştırın."],image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002FPRICE_CHART_WEB_JAN06.jpg",links:[{icon:a,text:"Öğrenim ücreti hakkında detaylar",link:"\u002Ftr\u002Fprice"}]},{title:"No.2: Harika Konum",subtitle:"Westwood & Hollywood : popular areas in Los Angeles",description:["Los Angeles, \u003Cb\u003EWestwood\u003C\u002Fb\u003E ve \u003Cb\u003EHollywood\u003C\u002Fb\u003E'un büyük ve popüler bölgelerinde bulunuyoruz. Öğrenciler Santa Monica ve LA şehir merkezi gibi ünlü yerlere kolayca ulaşabilirler."],image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002Fgreat-location.jpg",locations:[{image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002Fwestwood-campus.jpg",label:"Westwood Kampüsü"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002Fhollywood-campus.jpg",label:"Hollywood Kampüsü"}],links:[{icon:a,text:"Westwood Kampüsü hakkında detaylar",link:"\u002Ftr\u002Fwestwood"},{icon:a,text:"Hollywood Kampüsü hakkında detaylar",link:"\u002Ftr\u002Fhollywood"}]},{title:"No.3: College Hazırlık Kurslarının Çeşitliliği",subtitle:"Birçok öğrenci MLI'da okuduktan sonra UCLA ve Santa Monica Koleji'ne geçmektedir.",description:["\u003Cb\u003ETOEFL®, IELTS™\u003C\u002Fb\u003E gibi popüler test hazırlama programlarını sunuyoruz. Birçok öğrenci, sınav hazırlık programımızı tamamladıktan sonra \u003Cb\u003EUCLA, USC\u003C\u002Fb\u003E ve \u003Cb\u003ESanta Monica College\u003C\u002Fb\u003E'a transfer olmaktadır."],image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002Fgoing-to-college.jpg",links:[{icon:a,text:"College'a gitme hakkında detaylar",link:"\u002Ftr\u002Fgoing-to-college"}]},{title:"No.4: Esnek Sınıf Takvimi",subtitle:"Sabah, öğleden sonra ve akşam sınıfları sunuyoruz.",description:["MLI, 3 farklı sınıf programı sunar. Öğrenciler sabah, öğleden sonra ve akşam dersleri arasından seçim yapabilir."],image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002Fclass-schedule.png",notes:"※Bu Westwood Kampüsü için olan bir ders programı. Hollywood Kampüsü programına ait programı görmek isterseniz, lütfen bizimle iletişime geçin."},{title:"No.5: Yurtlar",subtitle:"İş Ortağımız: ABD Destek Hizmetleri A.Ş., yurt içinde tüm dünyadan öğrencilerle iletişim kurma fırsatı sunmaktadır.",description:["Ortağımız: ABD Destek Servisi A.Ş., aile yanında konaklama programları ve yurtlar düzenlemektedir. Her kampüsün yakınında bulunan yurtlarımızda 40'dan fazla oda bulunmaktadır. Birçok öğrenci, Amerika'da ilk defalarsa, bir yurtta kalır."],image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002Fdormitory.jpg",links:[{icon:a,text:"Konaklama hakkında detaylar",link:"\u002Ftr\u002Fstay"}]}],dir:"\u002Ffeature",path:"\u002Ffeature\u002Ftr",extension:".json",createdAt:"2026-10-22T16:31:29.236Z",updatedAt:"2026-03-24T13:34:16.460Z"}}],fetch:{},mutations:void 0}}("\u002Fimages\u002Ficons\u002Fboxed-arrow.svg")));